 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;
 using OpenAI;

 // --- Configuration -----------------------------------------------------------

 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable before running this app.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Build the chat client (MEAI abstraction) --------------------------------

 IChatClient chatClient = new OpenAIClient(apiKey)
     .GetChatClient(modelId)
     .AsIChatClient();

 // --- Define tools ------------------------------------------------------------

 var notebook = new ResearchNotebook();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(notebook.SaveNote),
     AIFunctionFactory.Create(notebook.GetNotes),
     AIFunctionFactory.Create(WebSearchTool.SearchWeb),
     AIFunctionFactory.Create(WebSearchTool.ReadWebPage),
 };

 // --- Create the agent (Microsoft Agent Framework) ----------------------------

 const string instructions = """
     You are a research agent. When given a topic you:
     1. Search the web for relevant information (2-3 searches with different queries).
     2. Read the most promising pages to gather details.
     3. Save important findings as notes using the note-taking tool.
     4. After gathering enough information, retrieve all your notes and produce a
        well-structured summary with key findings and source URLs.
     Be thorough but concise. Always cite your sources.
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "Researches topics using web search and note-taking tools",
     tools: tools);

 // --- Run the agent -----------------------------------------------------------

 Console.WriteLine("=== Research Agent ===");
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine();

 if (string.IsNullOrWhiteSpace(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\nResearching: {topic}\n");

 var session = await agent.CreateSessionAsync();
 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 4096,
 });

 var response = await agent.RunAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     session,
     runOptions);

 Console.WriteLine(response.Text);

