 /// <summary>Provides web search and page reading capabilities.</summary>
 static partial class WebSearchTool
 {
     private static readonly HttpClient s_http = new()
     {
         Timeout = TimeSpan.FromSeconds(15),
         DefaultRequestHeaders =
         {
             { "User-Agent", "ResearchAgent/1.0" },
             { "Accept", "text/html" },
         },
     };

     [Description("Search the web for a query and return a list of result URLs with snippets.")]
     public static async Task<string> SearchWeb(
         [Description("The search query")] string query)
     {
         try
         {
             var encoded = WebUtility.UrlEncode(query);
             // Use DuckDuckGo HTML-only endpoint (no API key required)
             var url = $"https://html.duckduckgo.com/html/?q={encoded}";
             var html = await s_http.GetStringAsync(url);

             var results = ParseDuckDuckGoResults(html);
             if (results.Count == 0)
             {
                 return $"No results found for: {query}";
             }

             var sb = new StringBuilder();
             sb.AppendLine($"Search results for: {query}");
             foreach (var (title, link, snippet) in results.Take(5))
             {
                 sb.AppendLine($"- [{title}]({link})");
                 sb.AppendLine($"  {snippet}");
             }

             return sb.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed: {ex.Message}";
         }
     }

     [Description("Read a web page and return its text content (truncated to ~4000 chars).")]
     public static async Task<string> ReadWebPage(
         [Description("The full URL of the page to read")] string url)
     {
         try
         {
             var html = await s_http.GetStringAsync(url);
             var text = StripHtml(html);

             const int maxLength = 4000;
             if (text.Length > maxLength)
             {
                 text = text[..maxLength] + "\n[...truncated]";
             }

             return $"Content from {url}:\n{text}";
         }
         catch (Exception ex)
         {
             return $"Failed to read {url}: {ex.Message}";
         }
     }

     private static List<(string Title, string Url, string Snippet)> ParseDuckDuckGoResults(string html)
     {
         var results = new List<(string, string, string)>();

         foreach (var match in ResultLinkRegex().Matches(html).Cast<Match>())
         {
             var rawUrl = WebUtility.HtmlDecode(match.Groups[1].Value);
             var title = StripHtml(match.Groups[2].Value).Trim();

             // DuckDuckGo wraps links through a redirect; extract the actual URL
             var actualUrl = ExtractRedirectUrl(rawUrl) ?? rawUrl;
             if (string.IsNullOrWhiteSpace(title) || string.IsNullOrWhiteSpace(actualUrl))
             {
                 continue;
             }

             // Find the snippet in the next <a class="result__snippet"> element
             var snippetMatch = SnippetRegex().Match(html, match.Index);
             var snippet = snippetMatch.Success
                 ? StripHtml(snippetMatch.Groups[1].Value).Trim()
                 : "";

             results.Add((title, actualUrl, snippet));
         }

         return results;
     }

     private static string? ExtractRedirectUrl(string ddgUrl)
     {
         if (!ddgUrl.Contains("uddg=", StringComparison.Ordinal))
         {
             return null;
         }

         var uddgIndex = ddgUrl.IndexOf("uddg=", StringComparison.Ordinal) + 5;
         var endIndex = ddgUrl.IndexOf('&', uddgIndex);
         var encoded = endIndex > 0
             ? ddgUrl[uddgIndex..endIndex]
             : ddgUrl[uddgIndex..];

         return WebUtility.UrlDecode(encoded);
     }

     private static string StripHtml(string html)
     {
         var text = HtmlTagRegex().Replace(html, " ");
         text = WebUtility.HtmlDecode(text);
         text = WhitespaceRegex().Replace(text, " ");
         return text.Trim();
     }

     [GeneratedRegex("""<a[^>]+class="result__a"[^>]*href="([^"]*)"[^>]*>(.*?)</a>""", RegexOptions.Singleline)]
     private static partial Regex ResultLinkRegex();

